import sys, re, json, subprocess, importlib.util
sys.path.insert(0, '/tmp/grepspec_test')
OUT='/home/tirandagan.guest/naive-arm/output'
G='/usr/bin/grep'
def load(path, name):
    spec=importlib.util.spec_from_file_location(name, path); m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m); return m
spec = load(f'{OUT}/grep.py','grep').grep_syntax_spec
fails=0
def check(cond, msg):
    global fails
    if not cond: fails+=1; print("FAIL:", msg)

# ---- 1. option set vs --help / man ----
helptxt = subprocess.run([G,'--help'],capture_output=True,text=True).stdout
mantxt = open('/tmp/grep.man').read()
documented = set(re.findall(r'(?<![\w-])(--?[A-Za-z][\w-]*)', helptxt)) | set(re.findall(r'^\s+(-[A-Za-z]|--[\w-]+)', mantxt, re.M))
documented = {d for d in documented if d not in ('-NUM','--regexp=PATTERNS')}
documented -= {'-egrep','--help=x'}
# --help text contains option names with =ARG; strip
documented = {re.sub(r'=.*','',d) for d in documented}
documented -= {'-grep'}  # noise from 'bug-grep'
allnodes = spec[1][0]   # superset (common + -e/-f)
spelled = {s for n in allnodes for s in n.spellings()}
print("spec spellings:", len(spelled))
missing = sorted(documented - spelled); extra = sorted(spelled - documented)
print("documented but not in spec:", missing)
print("in spec but not documented:", extra)
check(set(missing) <= {'-NUM'}, "missing documented options")
check(set(extra) <= {'-y','-u','--unix-byte-offsets'}, "undocumented extras besides -y/-u")

# ---- 2. every spelling accepted by the binary ----
def run(args, stdin=''):
    p=subprocess.run([G]+args,input=stdin,capture_output=True,text=True); return p.returncode, p.stdout, p.stderr
sample_value={'Integer':'1','String':'LBL','Separator':'::','Glob':'*.x','Path':'/tmp/pats','Regex':'beta'}
bad_value={'Integer':'abc','Selection':'bogus'}
for n in allnodes:
    for s in n.spellings():
        if s in ('--help','-V','--version'):
            rc,o,e=run([s]); check(rc==0 and o, f"{s} should print and exit 0"); continue
        if n.kind=='Flag':
            argsets=[[s,'beta','/tmp/t.txt']]
        elif n.kind=='Selection':
            argsets=[]
            for c in n.choices:
                argsets.append([f'{s}={c}','beta','/tmp/t.txt'] if n.eq or s.startswith('--') else [s,c,'beta','/tmp/t.txt'])
            # also space form for long options with mandatory arg
            if not n.eq and s.startswith('--'):
                argsets.append([s,n.choices[0],'beta','/tmp/t.txt'])
            # bad choice must be rejected
            bad=[f'{s}=bogus','beta','/tmp/t.txt'] if (n.eq or s.startswith('--')) else [s,'bogus','beta','/tmp/t.txt']
            rc,o,e=run(bad); check(rc!=0 or 'Usage' in o, f"{bad} accepted bogus choice (rc={rc})")
        else:
            v=sample_value[n.kind]
            if n.flag in ('-e','-f'):
                argsets=[[s,v,'/tmp/t.txt'], [f'{s}={v}','/tmp/t.txt'] if s.startswith('--') else [s+v,'/tmp/t.txt']]
            else:
                argsets=[[s,v,'beta','/tmp/t.txt'], [f'{s}={v}','beta','/tmp/t.txt'] if s.startswith('--') else [s+v,'beta','/tmp/t.txt']]
            if n.kind=='Integer':
                rc,o,e=run([s,'abc','beta','/tmp/t.txt']); check(rc==2, f"{s} abc should be rejected")
                if n.min==0:
                    rc,o,e=run([s,'-1','beta','/tmp/t.txt']); check(rc==2, f"{s} -1 should be rejected (min=0)")
                    rc,o,e=run([s,'0','beta','/tmp/t.txt']); check(rc==0, f"{s} 0 should be accepted")
                else:
                    rc,o,e=run([s,'-1','beta','/tmp/t.txt']); check(rc==0, f"{s} -1 should be accepted")
        for a in argsets:
            rc,o,e=run(a)
            check('unrecognized option' not in e and 'invalid option' not in e and 'Usage:' not in o and rc in (0,1), f"{a}: rc={rc} err={e.strip()[:80]}")
# dash_as_stdin
rc,o,e=run(['beta','-'],stdin='x\nbeta\n'); check(rc==0 and o=='beta\n', "- operand as stdin")
rc,o,e=run(['-f','-','/tmp/t.txt'],stdin='gamma\n'); check(rc==0 and o=='gamma\n', "-f - reads patterns from stdin")
# two syntaxes: -e form has no pattern operand
rc,o,e=run(['-e','beta','/tmp/t.txt']); check(o.count('beta')==2, "-e form: first operand is a FILE")
rc,o,e=run(['beta']); check(rc==1, "no FILE -> stdin (empty)")
# --color without =
rc,o,e=run(['--color','beta','/tmp/t.txt']); check(rc==0 and 'beta' in o, "--color bare")

# ---- 3. json consistency with the syntax spec ----
j=json.load(open(f'{OUT}/pash/grep.json'))
jflags={s for ent in j['flag'] for s in (ent if isinstance(ent,list) else [ent])}
jopts={s for ent in j['option'] for s in ent[:-1]}
sflags={s for n in allnodes if n.kind=='Flag' for s in n.spellings()}
sopts={s for n in allnodes if n.kind!='Flag' for s in n.spellings()}
check(jflags==sflags, f"json flags differ: {jflags^sflags}")
check(jopts==sopts, f"json options differ: {jopts^sopts}")
check(jflags.isdisjoint(jopts), "flag/option overlap")

# ---- 4. generators ----
IO=load(f'{OUT}/pash/InputOutputInfoGeneratorGrep.py','io').InputOutputInfoGeneratorGrep
PA=load(f'{OUT}/pash/ParallelizabilityInfoGeneratorGrep.py','pa').ParallelizabilityInfoGeneratorGrep
cases=[ (['-n'],['pat']), ([],['pat','f1']), ([],['pat','f1','f2']), (['-e'],[]), (['-e'],['f1']), (['-q'],['pat','f1']), (['-r'],['pat']), (['-r'],['pat','dir']), (['-f'],['f1']), (['-c'],['pat']), (['-l'],['pat']), (['-L'],['pat']), (['-b'],['pat']), (['-n','-b'],['pat']), (['-m'],['pat']), (['-A'],['pat']), (['-z'],['pat']), (['-o','-v'],['pat'])]
for fl,ops in cases:
    io=IO(fl,ops); io.generate_info(); pa=PA(fl); pa.generate_info()
    print(f"{str(fl):14} {str(ops):22} IO={io.log}  PAR={pa.pl} comm={pa.comm}")
exp={(): ['set_implicit_use_of_stdout','set_first_operand_as_config_arg_type_string','all_but_first_operand_is_streaming_input','set_implicit_use_of_stdin']}
io=IO([],['pat']); io.generate_info(); check(io.log==exp[()], "plain grep pat IO")
io=IO(['-q'],['pat','f']); io.generate_info(); check('set_implicit_use_of_stdout' not in io.log and 'set_implicit_use_of_stdin' not in io.log, "-q with file")
io=IO(['-r'],['pat']); io.generate_info(); check('set_implicit_use_of_stdin' not in io.log, "-r no file -> no stdin")
io=IO(['-e'],[]); io.generate_info(); check('set_implicit_use_of_stdin' in io.log and 'all_operands_are_streaming_inputs' in io.log, "-e no operands")
for fl in (['-q'],['-m'],['-A'],['-C'],['-z'],['-c'],['-l'],['-n']):
    pa=PA(fl); pa.generate_info(); check(pa.pl==[], f"{fl} should yield no parallelizer")
for fl in ([],['-o'],['-v','-i'],['-x','-w','-E']):
    pa=PA(fl); pa.generate_info(); check([p[0] for p in pa.pl]==['cc','rr'] and all(p[1]=='seq' and p[2]=='conc' for p in pa.pl), f"{fl} should be cc+rr seq conc")
print("TOTAL FAILURES:", fails)
EOF
python3 -I run_tests.py

